<?php
namespace CmuLms;
final class Announcement extends Model {public static function forCourse(int $course,bool $includeHidden=false):array{$includeHidden=$includeHidden||(($_SESSION['user']['role']??'')!=='student');$visibility=$includeHidden?'':'AND a.is_visible=1 ';return self::all('SELECT a.*,u.name author_name FROM announcements a JOIN users u ON u.id=a.author_id WHERE a.course_id=? '.$visibility.'AND (a.publish_at IS NULL OR a.publish_at<=NOW()) ORDER BY a.pinned DESC,a.created_at DESC',[$course]);}public static function comments(int $announcement):array{return self::all('SELECT c.*,u.name user_name FROM announcement_comments c JOIN users u ON u.id=c.user_id WHERE c.announcement_id=? ORDER BY c.created_at ASC',[$announcement]);}public static function attachments(int $announcement):array{return self::all('SELECT * FROM announcement_attachments WHERE announcement_id=? ORDER BY created_at',[$announcement]);}}
